<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="任务名称"><el-input v-model="query.name" clearable @keyup.enter="load" /></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-button type="primary" icon="Plus" @click="openAdd" v-hasPermi="['research:backtest:add']">新建回测</el-button><el-table v-loading="loading" :data="rows" class="mt12"><el-table-column prop="name" label="任务名称"/><el-table-column prop="symbol" label="品种" width="120"/><el-table-column prop="timeframe" label="周期" width="100"/><el-table-column prop="initialCapital" label="初始资金" width="120"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="totalReturn" label="收益" width="100"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="remove(row)" v-hasPermi="['research:backtest:remove']">删除</el-button></template></el-table-column></el-table><pagination v-show="total" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/><el-dialog v-model="dialog" title="新建回测" width="500px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="任务名称" prop="name"><el-input v-model="form.name"/></el-form-item><el-form-item label="组合ID" prop="combinationId"><el-input-number v-model="form.combinationId" :min="1"/></el-form-item><el-form-item label="品种" prop="symbol"><el-input v-model="form.symbol" placeholder="EURUSD"/></el-form-item><el-form-item label="周期" prop="timeframe"><el-input v-model="form.timeframe" placeholder="15m"/></el-form-item><el-form-item label="初始资金"><el-input-number v-model="form.initialCapital" :min="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="ResearchBacktest">import { addBacktest, delBacktest, listBacktest } from '@/api/project-research/research'
const { proxy } = getCurrentInstance(); const loading=ref(false),dialog=ref(false),total=ref(0),rows=ref([]),formRef=ref(); const query=reactive({pageNum:1,pageSize:10,name:undefined}); const form=reactive({}); const rules={name:[{required:true,message:'任务名称不能为空'}],combinationId:[{required:true,message:'请输入组合ID'}],symbol:[{required:true,message:'请输入品种'}],timeframe:[{required:true,message:'请输入周期'}]}; function load(){loading.value=true;listBacktest(query).then(r=>{rows.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)} function openAdd(){Object.assign(form,{name:'',combinationId:undefined,symbol:'EURUSD',timeframe:'15m',initialCapital:100000,status:'pending'});dialog.value=true} function save(){formRef.value.validate(v=>{if(v)addBacktest(form).then(()=>{proxy.$modal.msgSuccess('创建成功');dialog.value=false;load()})})} function remove(r){proxy.$modal.confirm('确认删除该回测任务吗？').then(()=>delBacktest(r.id)).then(load)} load()</script><style scoped>.mt12{margin-top:12px}</style>
